      end
      local localPlayer = localplayer.LocalPlayer
      local localplayer = localPlayer and (localPlayer:FindFirstChildOfClass("PlayerGui"))
      d = localplayer and localplayer:FindFirstChild(kespguiname.kEspGuiName)
      if d then
        d:Destroy()
      end
      if w.enabled then
        w:setupruntime()
      end
      return w
    end
  end
end

